import{_ as r,C as o,o as n,c as i,j as t,a,E as h,a6 as c}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/reuse-forecast.png",l="/screenshots/run-reused-tests.png",y=JSON.parse(`{"title":"Reuse forecast","description":"How much of a project's recent test time ran code identical to an earlier pass, read from recorded coverage, and the tests that failed with their code unchanged.","frontmatter":{"title":"Reuse forecast","description":"How much of a project's recent test time ran code identical to an earlier pass, read from recorded coverage, and the tests that failed with their code unchanged.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/reuse-forecast.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/reuse-forecast.html"}],["meta",{"property":"og:title","content":"Reuse forecast | Piwi for Playwright"}],["meta",{"property":"og:description","content":"How much of a project's recent test time ran code identical to an earlier pass, read from recorded coverage, and the tests that failed with their code unchanged."}]]},"headers":[],"relativePath":"features/reuse-forecast.md","filePath":"features/reuse-forecast.md","lastUpdated":1794398377000}`),u={name:"features/reuse-forecast.md"};function p(f,e,m,g,w,b){const s=o("Needs");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"reuse-forecast",tabindex:"-1"},[a("Reuse forecast "),t("a",{class:"header-anchor",href:"#reuse-forecast","aria-label":'Permalink to "Reuse forecast"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("The reuse forecast answers two questions from the coverage your runs already record: how much of the last month's test time re-ran code that had already passed unchanged, and which tests failed even though the code they ran had not changed. It lives on a project's "),t("strong",null,"Selections"),a(" tab and in the "),t("code",null,"get_reuse_forecast"),t("a",{href:"/reference/mcp-tools.html#workflow"},"MCP tool"),a(".")],-1)),h(s,{reporter:"",fixtures:""}),e[2]||(e[2]=c('<figure><img src="'+d+'" alt="Pass reuse forecast card: 15% of the test time ran code identical to an earlier pass, and one test that needed a retry with its code unchanged in two browsers"><figcaption>The pass reuse forecast: the test time a run could have skipped, and the tests that failed or retried anyway.</figcaption></figure><h2 id="what-counts-as-reusable" tabindex="-1">What counts as reusable <a class="header-anchor" href="#what-counts-as-reusable" aria-label="Permalink to &quot;What counts as reusable&quot;">​</a></h2><p>The forecast reads the 30 days before the project&#39;s latest run. A result is <strong>reusable</strong> when an earlier result of the same test, in the same Playwright project and another run, passed on its first attempt, is at most 14 days older, and either:</p><ul><li>recorded file versions (runtime, path and git blob) that are all among the versions the result itself ran;</li><li>or ran at the same commit, both runs on CI, which also counts a failure that stopped before reaching code the pass ran.</li></ul><p>The code that pass ran had not changed, so a run could have skipped the result and kept the pass. The card gives the share of test time that was reusable, split between the <a href="/features/branches.html">default branch</a> and the other branches when both have results: a branch&#39;s results may match a pass recorded on the default branch, since the comparison is by content, not by branch.</p><h2 id="failed-with-the-code-unchanged" tabindex="-1">Failed with the code unchanged <a class="header-anchor" href="#failed-with-the-code-unchanged" aria-label="Permalink to &quot;Failed with the code unchanged&quot;">​</a></h2><p>A reusable result that failed, or passed only on a retry, ran code identical to an earlier pass. Its failure came from the test, its data or its environment, not from a change to the application. The card lists those tests, each with the failing execution and the pass it matched, which is strong evidence when you investigate a <a href="/features/flaky-tests.html">flaky test</a>.</p><h2 id="what-it-needs-and-its-limits" tabindex="-1">What it needs, and its limits <a class="header-anchor" href="#what-it-needs-and-its-limits" aria-label="Permalink to &quot;What it needs, and its limits&quot;">​</a></h2><ul><li><strong>Coverage with file versions</strong>: <a href="/features/code-reach.html">code reach</a> at <code>coverage.browser: &#39;functions&#39;</code> or <code>&#39;lines&#39;</code>, or <a href="/features/server-coverage.html">server coverage</a>. With <code>&#39;files&#39;</code> a test records which files it ran but not their version. A pass stands in for a later result only when it recorded file versions; a result that recorded none is reusable only at the same CI commit as such a pass.</li><li><strong>An upper bound.</strong> The comparison sees the application files coverage records. A change to the test code itself, to the Playwright configuration or to a dependency is not part of it, and would make more tests run.</li><li><strong>Runs that do not count</strong>: Flake Lab, probe, bisect, reproduction, <code>piwi bug</code> and private runs, and runs flagged as an <a href="/features/environment-incidents.html">environment incident</a>.</li></ul><h2 id="skipping-reusable-tests" tabindex="-1">Skipping reusable tests <a class="header-anchor" href="#skipping-reusable-tests" aria-label="Permalink to &quot;Skipping reusable tests&quot;">​</a></h2><p><strong>Experimental.</strong> With the pass reuse capability on, <code>piwi plan</code> and <code>piwi run --reuse</code> skip the tests the forecast would count as reusable, with a stricter rule. A test&#39;s pass stands in for it only when that pass came from a clean checkout of a commit, with the same Playwright version, and every result of the test in that run passed on its first attempt with coverage naming its file versions. The working tree is diffed against that commit: the test runs when <a href="/features/change-impact.html">impact from that diff</a> selects it, when a changed file maps to no test, or when a file the pass ran changed. A test that is quarantined, in an open failure cluster, failed or was retried in its last 20 executions, tagged <code>@no-reuse</code>, or in a spec file holding a serial group always runs. A run skips only the tests the plan names, in the Playwright projects their pass ran them in, so a new or renamed test runs. The run records the tests it skipped and did not execute as its reused results: the run page&#39;s header counts them and lists them with the pass each one reuses, the pull-request comment counts them, and the <code>get_run</code> MCP tool returns their count. The run&#39;s own status, pass rate, flaky scores, durations and fix verification read executions only. In a run that passed with no run error, the <a href="/reference/cli.html#gate">CI gate</a> counts a reused test as passed for its tag and selection rules, and <code>--max-reused</code> and <code>--require-executed</code> limit reuse. A run that claimed a plan it was not made for (another commit, a dirty checkout, another Playwright version, an expired plan) records no reuse and fails those two rules. A run whose shards&#39; blob reports are merged by <code>merge-reports</code> claims no plan, so its reuse is not recorded.</p><figure><img src="'+l+'" alt="Reused tests of a run: each test with its file and Playwright project, and a link to the earlier pass at its commit"><figcaption>A run whose plan skipped every test: each reused test with the pass that stood in for it.</figcaption></figure><p>Commands: <a href="/reference/cli.html#plan"><code>plan</code></a>. Design record: <a href="https://github.com/PiwiTests/piwi/blob/main/proposals/pass-reuse.md" target="_blank" rel="noreferrer">pass reuse</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/test-selection.html">Test selections</a>: saved subsets, balanced shards and the CI guard</li><li><a href="/features/change-impact.html">Impact from a diff</a>: the tests a change affects, down to the changed lines</li><li><a href="/features/code-reach.html">Code reach</a>: what each test records about the code it runs</li></ul>',15))])}const k=r(u,[["render",p]]);export{y as __pageData,k as default};
